/**
 * @file tree-card-v2.tsx
 * SolidJS-compatible implementation of the Tree Card using legacy wrapper
 */

import { createEffect, createMemo, createSignal, For, onCleanup, onMount, Show, type Component } from "solid-js";

import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { RingMeter } from "#core/ui-next/components/ring-meter.jsx";
import { TooltipHorizontalPosition, TooltipVerticalPosition } from "#core/ui-next/components/tooltip.jsx";

import {
	TreeCardActivatedEventName,
	TreeCardDehoveredEventName,
	TreeCardHoveredEventName,
} from "#base/ui/tree-grid/tree-card.js";
import { ScaleTreeCardEventName, TreeClassSelector, type TreeGridDepthInfo } from "#base/ui/tree-grid/tree-support.js";
import { getNodeNameFromType } from "#base/ui/utilities/utilities-textprovider.js";
import { convertLegacyDepthInfo } from "#base/ui-next/screens/choosers/helpers.js";
import { TechCivicTooltip } from "#base/ui-next/tooltips/tech-civic-tooltip.jsx";

const MASTERY_ICON_PATH = "blp:techtree_icon-II.png";

type Attrs = Readonly<Record<string, string | null>>;

function parseNumber(v: string | null | undefined, fallback = 0): number {
	if (v == null) return fallback;
	const n = Number(v);
	return Number.isFinite(n) ? n : fallback;
}

function parseJSON<T>(v: string | null | undefined, fallback: T): T {
	if (!v) return fallback;
	try {
		return JSON.parse(v) as T;
	} catch {
		return fallback;
	}
}

interface NodeCardProps {
	depth: TreeGridDepthInfo | undefined;
	level: number;
	isMastery?: boolean;
	disableTooltip?: boolean;
	// Context from host/parent
	el: Element;
	treeType: string;
	dummy: boolean;
	audio: { group?: string; onActivate?: string; onFocus?: string };
	type: string;
	name: string;
	queueOrder: string;
	turns: number;
	cost: number;
	unlocksByDepth: TreeGridDepthInfo[];
	progress: number;
}

const NodeCard: Component<NodeCardProps> = (props) => {
	const iconURL = createMemo(() => (props.isMastery ? MASTERY_ICON_PATH : (props.depth?.iconURL ?? "")));
	const isLocked = createMemo(() => props.depth?.isLocked ?? false);
	const isCompleted = createMemo(() => props.depth?.isCompleted ?? false);
	const isCurrent = createMemo(() => props.depth?.isCurrent ?? false);

	const getDisplayedProgress = (depth: TreeGridDepthInfo | undefined) => {
		if (!depth) return 0;
		if (depth.isCompleted) return 100;
		if (depth.isLocked) return 0;
		return props.progress;
	};
	const value = createMemo(() => getDisplayedProgress(props.depth));

	// Helpers for events
	function dispatch(name: string, detail: { type: string; level: string }) {
		props.el.dispatchEvent(new CustomEvent(name, { bubbles: false, cancelable: true, detail }));
	}

	const onHover = () => dispatch(TreeCardHoveredEventName, { type: props.type, level: String(props.level) });
	const onDehover = () => dispatch(TreeCardDehoveredEventName, { type: props.type, level: String(props.level) });
	const onActivate = () => {
		dispatch(TreeCardActivatedEventName, { type: props.type, level: String(props.level) });
	};

	const showTurns = createMemo(() => !(isLocked() || isCompleted()));
	const treeTypeClass = createMemo(() => (props.treeType === "culture" ? "tree-type-culture" : "tree-type-tech"));

	// Convert legacy TreeGridDepthInfo to ChooserDepthInfo for the tooltip
	const convertedUnlocksByDepth = createMemo(() => convertLegacyDepthInfo(props.unlocksByDepth));

	const displayName = createMemo(() => {
		const nodeType = GameInfo.ProgressionTreeNodes.lookup(Number(props.type))?.ProgressionTreeNodeType ?? "";
		const player = Players.get(GameContext.localPlayerID);
		return getNodeNameFromType(nodeType, props.level, player);
	});

	const renderContent = () => (
		<fxs-activatable
			class={"pointer-events-auto relative tree-card-hitbox"}
			classList={{
				[treeTypeClass()]: true,
				"current-research": isCurrent(),
				completed: isCompleted(),
				hidden: props.dummy,
				relative: !!props.isMastery,
				"-top-3": !!props.isMastery,
				"tree-card--mastery": !!props.isMastery,
				"parent-node": !props.isMastery,
			}}
			id={`tree-card-type-${props.type}`}
			tabIndex={-1}
			name="TreeCard-Hitbox"
			audio={props.audio}
			disableFocus={isLocked()}
			data-level={String(props.level)}
			data-type={props.type}
			onMouseEnter={onHover}
			onMouseLeave={onDehover}
			onFocus={onHover}
			on:action-activate={onActivate}
		>
			<div
				class={`absolute bg-center bg-no-repeat pointer-events-none ${
					props.isMastery
						? "tree-card__child-bg--base tree-card-child-background"
						: "tree-card__bg--base tree-card-background pt-px"
				}`}
			/>

			<div
				class={`card-background bg-center bg-no-repeat relative flex flex-row pointer-events-none ${
					props.isMastery ? "tree-card-child-bg" : "tree-card-bg pt-px"
				}`}
			>
				<div class="tree-card-progress flex flex-col items-center justify-center pointer-events-none relative">
					<div class="flex relative justify-center items-center">
						<RingMeter
							class="ring-size card-ring flex justify-center bg-contain bg-center flex-auto items-center absolute"
							max={100}
							min={0}
							value={value()}
							ringImage={
								props.treeType == "culture"
									? 'url("blp:hud_civic_circle_rad.png")'
									: 'url("blp:hud_tech_circle_rad.png")'
							}
						>
							<div
								class="tree-node-icon bg-cover bg-center self-center"
								style={{ "background-image": `url(${iconURL()})` }}
							/>
						</RingMeter>
					</div>
				</div>
				<div class="tree-card-name-unlocks flex flex-col flex-initial w-full justify-between">
					<div class="tree-card-name-container relative flex flex-row justify-between items-center">
						<div
							class="tree-card-name font-title text-base flex-initial tracking-150 truncate font-fit-shrink"
							classList={{ "pr-6": isCompleted() }}
						>
							<L10n.Compose text={displayName()} />
						</div>

						<Show when={props.level === 0}>
							<div class="tree-card-queue-order font-body text-xs text-accent-2 mr-1 hidden">
								<L10n.Compose text={props.queueOrder} />
							</div>
						</Show>

						<div
							class="turn-text font-body text-xs shrink-0 ml-2 mr-1"
							classList={{ hidden: !showTurns() }}
						>
							<L10n.Compose
								text="LOC_NARRATIVE_TURN_TIMER"
								args={[props.turns]}
							/>
						</div>
					</div>

					<div class="tree-card-unlocks flex items-center mt-1 pointer-events-none relative">
						<For each={props.depth?.unlocks ?? []}>
							{(unlock) => {
								const icon = unlock.icon ? unlock.icon : UI.getIconURL("MOD_GENERIC_BONUS");
								return (
									<div
										class="unlock-item bg-no-repeat bg-contain bg-center mr-1"
										style={{ "background-image": `url(${icon})` }}
									/>
								);
							}}
						</For>
					</div>
				</div>

				{/* Completed checkmark overlay */}
				<Show when={isCompleted()}>
					<div
						class="check-icon flex absolute size-6 bg-no-repeat bg-center bg-contain right-4 top-3 justify-center items-center"
						style={{ "background-image": 'url("blp:techtree-icon-empty")' }}
					>
						<div
							class="size-4 bg-center bg-contain bg-no-repeat"
							style={{ "background-image": 'url("blp:techtree_icon-checkmark")' }}
						/>
					</div>
				</Show>
			</div>
		</fxs-activatable>
	);

	return (
		<Show
			when={!props.disableTooltip}
			fallback={renderContent()}
		>
			<TechCivicTooltip
				node={{
					name: displayName(),
					unlocksByDepth: convertedUnlocksByDepth(),
					cost: props.cost,
					currentDepthIndex: props.level,
				}}
				isCulture={props.treeType === "culture"}
				initialVPosition={TooltipVerticalPosition.CENTER}
				initialHPosition={TooltipHorizontalPosition.RIGHT}
				allowFlip={true}
				offset={10}
			>
				{renderContent()}
			</TechCivicTooltip>
		</Show>
	);
};

const TreeCard: Component<{
	attrs: Attrs;
	el: Element;
}> = (props) => {
	const type = createMemo(() => props.attrs["type"] ?? "");
	const name = createMemo(() => props.attrs["name"] ?? "");
	const queueOrder = createMemo(() => props.attrs["queue-order"] ?? "");
	const progress = createMemo(() => parseNumber(props.attrs["progress"], 0));
	const turns = createMemo(() => parseNumber(props.attrs["turns"], 0));
	const cost = createMemo(() => parseNumber(props.attrs["cost"], -1));
	const unlocksByDepth = createMemo(() => parseJSON<TreeGridDepthInfo[]>(props.attrs["unlocks-by-depth"], []));
	const dummy = createMemo(() => (props.attrs["dummy"] ?? "false") === "true");
	const disableTooltip = createMemo(() => (props.attrs["disable-tooltip"] ?? "false") === "true");

	const treeType = createMemo(() => props.el.getAttribute("tree-type") ?? "");
	const audioGroup = createMemo(() => props.el.getAttribute("data-audio-group-ref") ?? undefined);
	const audioActivate = createMemo(() => props.el.getAttribute("data-audio-activate-ref") ?? undefined);
	const audioFocus = createMemo(() => props.el.getAttribute("data-audio-focus") ?? undefined);

	// Card scale via global event
	const [scale, setScale] = createSignal(1);
	const onCardScale = (ev: CustomEvent<{ scale: number }>) => {
		setScale(ev.detail?.scale ?? 1);
	};
	onMount(() => {
		props.el.classList.add("min-h-10", "w-96", TreeClassSelector.CARD);
		window.addEventListener(ScaleTreeCardEventName, onCardScale);
	});
	onCleanup(() => {
		window.removeEventListener(ScaleTreeCardEventName, onCardScale);
	});

	createEffect(() => {
		(props.el as HTMLElement).style.fontSize = `${scale()}rem`;
		props.el.classList.toggle("dummy", dummy());
	});

	const mainDepth = createMemo(() => unlocksByDepth()[0]);
	const tiers = createMemo(() => unlocksByDepth().slice(1));

	return (
		<fxs-vslot
			class="main-container flex flex-col flex-auto pointer-events-none items-center"
			disableFocus
			style={{ "font-size": `${scale()}rem` }}
		>
			{/* Main card */}
			<NodeCard
				depth={mainDepth()}
				level={0}
				el={props.el}
				treeType={treeType()}
				dummy={dummy()}
				audio={{ group: audioGroup(), onActivate: audioActivate(), onFocus: audioFocus() }}
				type={type()}
				name={name()}
				queueOrder={queueOrder()}
				turns={turns()}
				cost={cost()}
				unlocksByDepth={unlocksByDepth()}
				progress={progress()}
				disableTooltip={disableTooltip()}
			/>

			{/* Mastery tiers */}
			<For each={tiers()}>
				{(depth, i) => (
					<NodeCard
						depth={depth}
						level={i() + 1}
						isMastery
						el={props.el}
						treeType={treeType()}
						dummy={dummy()}
						audio={{ group: audioGroup(), onActivate: audioActivate(), onFocus: audioFocus() }}
						type={type()}
						name={name()}
						queueOrder={queueOrder()}
						turns={turns()}
						cost={cost()}
						unlocksByDepth={unlocksByDepth()}
						progress={progress()}
						disableTooltip={disableTooltip()}
					/>
				)}
			</For>
		</fxs-vslot>
	);
};

// Register the legacy wrapper component
defineLegacyComponent(
	"tree-card-v2",
	{
		classNames: ["tree-card"],
		tabIndex: -1,
		attrs: {
			dummy: "false",
			type: "",
			name: "",
			progress: "0",
			turns: "0",
			cost: "",
			"tooltip-type": "",
			"unlocks-by-depth": "[]",
			"queue-order": "",
			"disable-tooltip": "false",
		},
	},
	(attrs, el) => (
		<TreeCard
			attrs={attrs}
			el={el!}
		/>
	),
);
